-- CargoHub legacy JSON import for Anmol's EF Core migrations.
-- DATA ONLY: first run dotnet ef database update --project api-csharp.
-- Execute with psql against your chosen database. No database is created or switched.
-- Does not delete/update existing records. All 15 target tables must be empty.
-- user.json is excluded: API key management is outside the EF Core model.
-- DateOnly fields use the source UTC date; the time of day is discarded.
\set ON_ERROR_STOP on
\encoding UTF8
BEGIN;
SET LOCAL TIME ZONE 'UTC';
SET LOCAL standard_conforming_strings = on;
SET LOCAL lock_timeout = '10s';

DO $preflight$
BEGIN
    IF to_regclass('public."__EFMigrationsHistory"') IS NULL THEN
        RAISE EXCEPTION 'EF Core migrations are missing. Run dotnet ef database update --project api-csharp first.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."__EFMigrationsHistory" WHERE "MigrationId" = '20261015111621_InitialBaseline') THEN
        RAISE EXCEPTION 'Required EF Core migration missing: 20261015111621_InitialBaseline';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."__EFMigrationsHistory" WHERE "MigrationId" = '20261015113203_EnforceApprovedPilotRules') THEN
        RAISE EXCEPTION 'Required EF Core migration missing: 20261015113203_EnforceApprovedPilotRules';
    END IF;
END;
$preflight$;

-- Block competing writers throughout the emptiness check and import.
LOCK TABLE public."warehouse", public."client", public."supplier", public."item_line", public."item_group", public."item_type", public."location", public."item", public."inventory", public."order", public."order_item", public."shipment", public."shipment_item", public."transfer", public."transfer_item" IN SHARE ROW EXCLUSIVE MODE;

DO $empty_check$
BEGIN
    IF EXISTS (SELECT 1 FROM public."warehouse") THEN
        RAISE EXCEPTION 'Import refused: public.warehouse is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."client") THEN
        RAISE EXCEPTION 'Import refused: public.client is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."supplier") THEN
        RAISE EXCEPTION 'Import refused: public.supplier is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."item_line") THEN
        RAISE EXCEPTION 'Import refused: public.item_line is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."item_group") THEN
        RAISE EXCEPTION 'Import refused: public.item_group is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."item_type") THEN
        RAISE EXCEPTION 'Import refused: public.item_type is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."location") THEN
        RAISE EXCEPTION 'Import refused: public.location is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."item") THEN
        RAISE EXCEPTION 'Import refused: public.item is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."inventory") THEN
        RAISE EXCEPTION 'Import refused: public.inventory is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."order") THEN
        RAISE EXCEPTION 'Import refused: public.order is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."order_item") THEN
        RAISE EXCEPTION 'Import refused: public.order_item is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."shipment") THEN
        RAISE EXCEPTION 'Import refused: public.shipment is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."shipment_item") THEN
        RAISE EXCEPTION 'Import refused: public.shipment_item is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."transfer") THEN
        RAISE EXCEPTION 'Import refused: public.transfer is not empty. No existing data has been changed.';
    END IF;
    IF EXISTS (SELECT 1 FROM public."transfer_item") THEN
        RAISE EXCEPTION 'Import refused: public.transfer_item is not empty. No existing data has been changed.';
    END IF;
END;
$empty_check$;

-- data/warehouse.json: 10 records, sha256: 406281e1767afd3aed0388f9b81dd8096005fb7dbd5a3985b012fd9e44babf84

-- data/client.json: 300 records, sha256: 4bd89691c473ba367a5766b264c0652fbb3180d298ef68e3faae5516c17e1ab4

-- data/supplier.json: 21 records, sha256: c628998a962fa0dd6ea6d73f8e5337c91651af30c3d2c4f18ed0bcba9d6d26a8

-- data/item_line.json: 14 records, sha256: ae19362f2082bc2add924afd0e387816c89903be8f303255c3d8ae606630105b

-- data/item_group.json: 3 records, sha256: 3f6e6eab3d82758e2034d737fce3e179efa24f538317aa2a974a658b3c892f8b

-- data/item_type.json: 3 records, sha256: c017a81dca98916b1154b51063208c51921d58fd14b7efff4b9ed7c248412596

-- data/location.json: 400 records, sha256: 43536a23da370bb4b67d6e2e35e67182059ee7a41cdfdd4d6d87ed232685aa6d

-- data/item.json: 600 records, sha256: 118f7a3d10f9f2b5fd55ec28043d856dc5b5eb7af66d2b2958c27d7b19dcbc68

-- data/inventory.json: 4800 records, sha256: 5f8bb30b5a6b6ea4d3be0100d04ba78c86206cfbd43c90c0c70df8dea3e16b2c

-- data/order.json: 4854 records, sha256: 9f9c2e7ec7d1dcdc5f0b877f237a14da980fe7dc03be5ff68b4c632d6dfe6e42

-- data/order_item.json: 26498 records, sha256: ae87586de45f9bdcbca39190efa54b7ed97b875c58fcfbb9113b3a72870ed6c6

-- data/shipment.json: 6132 records, sha256: 7990d38c4c43e6c19fa51f71cff7df2deeb7fed2ff056daca9c26d055e0916e7

-- data/shipment_item.json: 33660 records, sha256: cf0d8f646b229ed4f5f368d000a55321e405bbd3a2007cb89da5d6031e5ec3ed

-- data/transfer.json: 800 records, sha256: 5c8aa50d0c406b81671e96fb9086041abdef2926d5af5cf68b447e0238093727

-- data/transfer_item.json: 2370 records, sha256: 2cba53549817ee8ee5d4ebe92384898013e2f2f2a335a60ec3db389a9cee00f0

DO $verify_counts$
BEGIN
    IF (SELECT COUNT(*) FROM public."warehouse") <> 10 THEN
        RAISE EXCEPTION 'Unexpected record count in public.warehouse';
    END IF;
    IF (SELECT COUNT(*) FROM public."client") <> 300 THEN
        RAISE EXCEPTION 'Unexpected record count in public.client';
    END IF;
    IF (SELECT COUNT(*) FROM public."supplier") <> 21 THEN
        RAISE EXCEPTION 'Unexpected record count in public.supplier';
    END IF;
    IF (SELECT COUNT(*) FROM public."item_line") <> 14 THEN
        RAISE EXCEPTION 'Unexpected record count in public.item_line';
    END IF;
    IF (SELECT COUNT(*) FROM public."item_group") <> 3 THEN
        RAISE EXCEPTION 'Unexpected record count in public.item_group';
    END IF;
    IF (SELECT COUNT(*) FROM public."item_type") <> 3 THEN
        RAISE EXCEPTION 'Unexpected record count in public.item_type';
    END IF;
    IF (SELECT COUNT(*) FROM public."location") <> 400 THEN
        RAISE EXCEPTION 'Unexpected record count in public.location';
    END IF;
    IF (SELECT COUNT(*) FROM public."item") <> 600 THEN
        RAISE EXCEPTION 'Unexpected record count in public.item';
    END IF;
    IF (SELECT COUNT(*) FROM public."inventory") <> 4800 THEN
        RAISE EXCEPTION 'Unexpected record count in public.inventory';
    END IF;
    IF (SELECT COUNT(*) FROM public."order") <> 4854 THEN
        RAISE EXCEPTION 'Unexpected record count in public.order';
    END IF;
    IF (SELECT COUNT(*) FROM public."order_item") <> 26498 THEN
        RAISE EXCEPTION 'Unexpected record count in public.order_item';
    END IF;
    IF (SELECT COUNT(*) FROM public."shipment") <> 6132 THEN
        RAISE EXCEPTION 'Unexpected record count in public.shipment';
    END IF;
    IF (SELECT COUNT(*) FROM public."shipment_item") <> 33660 THEN
        RAISE EXCEPTION 'Unexpected record count in public.shipment_item';
    END IF;
    IF (SELECT COUNT(*) FROM public."transfer") <> 800 THEN
        RAISE EXCEPTION 'Unexpected record count in public.transfer';
    END IF;
    IF (SELECT COUNT(*) FROM public."transfer_item") <> 2370 THEN
        RAISE EXCEPTION 'Unexpected record count in public.transfer_item';
    END IF;
END;
$verify_counts$;

-- Transactional sequence resets: new IDs follow the existing IDs.
ALTER TABLE public."warehouse" ALTER COLUMN id RESTART WITH 11;
ALTER TABLE public."client" ALTER COLUMN id RESTART WITH 301;
ALTER TABLE public."supplier" ALTER COLUMN id RESTART WITH 22;
ALTER TABLE public."item_line" ALTER COLUMN id RESTART WITH 15;
ALTER TABLE public."item_group" ALTER COLUMN id RESTART WITH 4;
ALTER TABLE public."item_type" ALTER COLUMN id RESTART WITH 4;
ALTER TABLE public."location" ALTER COLUMN id RESTART WITH 401;
ALTER TABLE public."item" ALTER COLUMN id RESTART WITH 601;
ALTER TABLE public."order" ALTER COLUMN id RESTART WITH 4855;
ALTER TABLE public."order_item" ALTER COLUMN id RESTART WITH 26499;
ALTER TABLE public."shipment" ALTER COLUMN id RESTART WITH 6133;
ALTER TABLE public."shipment_item" ALTER COLUMN id RESTART WITH 33661;
ALTER TABLE public."transfer" ALTER COLUMN id RESTART WITH 801;
ALTER TABLE public."transfer_item" ALTER COLUMN id RESTART WITH 2371;

COMMIT;

-- Imported record counts:
SELECT 'warehouse' AS table_name, COUNT(*) AS records FROM public."warehouse"
UNION ALL
SELECT 'client' AS table_name, COUNT(*) AS records FROM public."client"
UNION ALL
SELECT 'supplier' AS table_name, COUNT(*) AS records FROM public."supplier"
UNION ALL
SELECT 'item_line' AS table_name, COUNT(*) AS records FROM public."item_line"
UNION ALL
SELECT 'item_group' AS table_name, COUNT(*) AS records FROM public."item_group"
UNION ALL
SELECT 'item_type' AS table_name, COUNT(*) AS records FROM public."item_type"
UNION ALL
SELECT 'location' AS table_name, COUNT(*) AS records FROM public."location"
UNION ALL
SELECT 'item' AS table_name, COUNT(*) AS records FROM public."item"
UNION ALL
SELECT 'inventory' AS table_name, COUNT(*) AS records FROM public."inventory"
UNION ALL
SELECT 'order' AS table_name, COUNT(*) AS records FROM public."order"
UNION ALL
SELECT 'order_item' AS table_name, COUNT(*) AS records FROM public."order_item"
UNION ALL
SELECT 'shipment' AS table_name, COUNT(*) AS records FROM public."shipment"
UNION ALL
SELECT 'shipment_item' AS table_name, COUNT(*) AS records FROM public."shipment_item"
UNION ALL
SELECT 'transfer' AS table_name, COUNT(*) AS records FROM public."transfer"
UNION ALL
SELECT 'transfer_item' AS table_name, COUNT(*) AS records FROM public."transfer_item"
